const $=s=>document.querySelector(s);
const views=['conversation','guided','worksheet'];
let view=new URLSearchParams(location.search).get('view')||'conversation';if(!views.includes(view))view='conversation';
let data={country:'IN',item:'',price:'',share:'',registration:''},step=0,screen='input',lastFocus=null;
const currency=()=>data.country==='GB'?'£':'₹';
const money=v=>currency()+Number(v).toLocaleString(data.country==='GB'?'en-GB':'en-IN',{maximumFractionDigits:2});
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const questions=[{key:'item',title:'What are you thinking of buying?',hint:'Start with the item. We’ll ask for the details that matter.',label:'Purchase',placeholder:'e.g. a laptop for freelance design work',type:'text'}, {key:'price',title:'What’s the total purchase price?',hint:'Use the amount you expect to pay, including any taxes on the quote.',label:'Total price',placeholder:'80,000',type:'number'}, {key:'share',title:'How much will you use it for work?',hint:'Give your best estimate. Personal use matters too.',label:'Business use (%)',placeholder:'70',type:'number'}, {key:'registration',title:'Do you know your registration status?',hint:'Registration can affect which tax rules apply. “Not sure” is a valid starting point.',label:'Tax registration',type:'select'}];
function rows(editable=false){return [['Purchase',data.item||'Not entered'],['Price',data.price?money(data.price):'Not entered'],['Business use',data.share!==''?data.share+'%':'Not entered'],['Registration',data.registration||'Not entered']].map(([k,v],i)=>`<div><dt>${k}</dt><dd class="${v==='Not entered'?'empty':''}">${esc(v)}${editable?` <button type="button" data-edit="${i}">Edit</button>`:''}</dd></div>`).join('');}
function summary(){return `<aside class="summary"><div class="summary-label"><span>Your purchase sheet</span><span>${data.country==='IN'?'India':'United Kingdom'}</span></div><div class="paper"><div class="paper-title"><span aria-hidden="true">▤</span> The facts so far</div><dl>${rows()}</dl></div><p class="summary-help"><span aria-hidden="true">ⓘ</span> Your answers stay editable. We’ll show what’s known and what still needs checking.</p></aside>`;}
function field(q){return `<label class="field-label" for="${q.key}">${q.label}</label>${q.type==='select'?`<select id="${q.key}" name="${q.key}"><option value="">Choose a status</option>${['Registered','Not registered','Not sure'].map(x=>`<option ${data[q.key]===x?'selected':''}>${x}</option>`).join('')}</select>`:`<div class="${q.key==='price'?'input-unit':''}">${q.key==='price'?`<span>${currency()}</span>`:''}<input id="${q.key}" name="${q.key}" type="${q.type}" ${q.type==='number'?`min="${q.key==='price'?'.01':'0'}" ${q.key==='share'?'max="100"':''} step="any" inputmode="decimal"`: 'maxlength="160"'} placeholder="${q.placeholder}" value="${esc(data[q.key])}" required></div>`}`;}
function inputScreen(){const q=questions[step];return `<div class="${view}"><div class="workspace"><div class="flow"><div class="flow-head"><span class="flow-icon" aria-hidden="true">✦</span><div><strong>Let’s check your purchase</strong><p>Four details to get started</p></div><span class="step-count">${screen==='review'?'Review':view==='worksheet'?'Purchase details':`${step+1} of 4`}</span></div>${view==='conversation'&&step>0&&screen!=='review'?`<div class="conversation-log" aria-label="Previous answers">${questions.slice(0,step).map((x,i)=>`<button data-edit="${i}" title="Edit ${x.label}">${esc(x.label)}: ${esc(data[x.key])}</button>`).join('')}</div>`:''}<div class="question">${screen==='review'?`<h2>Does everything look right?</h2><p>Review your facts before checking. You can change any answer.</p><dl class="review-list">${rows(true)}</dl><div class="actions"><button class="primary" id="check">Check this purchase <span aria-hidden="true">↗</span></button><button class="secondary" id="back">Go back</button></div><p class="quiet">Prototype: the next screen shows allocation, not tax eligibility.</p>`:`${view==='guided'?`<div class="progress" aria-label="Step ${step+1} of 4">${questions.map((_,i)=>`<span class="${i<=step?'done':''}"></span>`).join('')}</div>`:''}<h2>${view==='worksheet'?'Tell us about the purchase':q.title}</h2>${view==='worksheet'?'<p>Fill in what you know. You can review it before checking.</p>':`<p>${q.hint}</p>`}<form id="purchase-form" novalidate>${view==='worksheet'?`<div class="fields">${questions.map(x=>`<div>${field(x)}</div>`).join('')}</div>`:field(q)}${step===0&&view!=='worksheet'?`<div class="chips" aria-label="Example purchases"><button type="button" data-example="Laptop for freelance design">Laptop</button><button type="button" data-example="Camera for client shoots">Camera</button><button type="button" data-example="Phone for business use">Phone</button></div>`:''}<div id="error" class="error" role="alert"></div><div class="actions"><button type="submit" class="primary">${view==='worksheet'?'Review purchase':step===3?'Review answers':'Continue'} <span aria-hidden="true">↗</span></button>${step>0&&view!=='worksheet'?'<button type="button" id="back" class="secondary">Back</button>':''}</div><p class="quiet">No account needed. This prototype stores nothing.</p></form>`}</div></div>${summary()}</div></div>`;}
function resultScreen(){const portion=Number(data.price)*Number(data.share)/100;return `<div class="result"><div class="result-main"><span class="status"><span aria-hidden="true">○</span> Needs a rule check</span><h2>Your purchase facts are ready.</h2><p>${esc(data.item)} in ${data.country==='IN'?'India':'the United Kingdom'}. You’ve estimated ${esc(data.share)}% business use. The next step is checking the applicable tax rules.</p><div class="allocation"><span class="field-label">Business-use portion of the purchase</span><div class="amount">${money(portion)}</div><div class="formula">${money(data.price)} × ${esc(data.share)}% business use</div><small>This is purchase allocation, not a deduction or tax saving.</small></div><h3>What still needs checking</h3><p>Eligibility, the relevant tax period, purchase treatment, and your business circumstances. Verified rules are not connected in this prototype, so a tax benefit has not been assessed.</p><div class="actions"><button class="primary" id="edit-result">Edit purchase</button><button class="secondary" id="new-result">Check another item</button></div></div><aside class="result-side"><h3>Keep these together</h3><p>A sample purchase evidence checklist. Actual requirements will depend on the verified rules.</p><div class="checklist">${['Purchase invoice or quote','Proof of payment, once purchased','A record of how it’s used for work'].map((x,i)=>`<label><input type="checkbox" id="evidence-${i}">${x}</label>`).join('')}</div><button id="sources" class="source-link"><span>Sources & assumptions<small>Rule verification pending</small></span><span aria-hidden="true">↗</span></button><p class="quiet">Real results will show the legal source, effective period, calculation, and remaining conditions here.</p></aside></div>`;}
function render(){document.body.dataset.view=view;$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view));});$('#workspace').innerHTML=data.country==='CA'?`<div class="unsupported"><span class="status">Outside this prototype</span><h2>Canada isn’t covered here yet.</h2><p>Choose India or the United Kingdom to explore the sample workflow. No country’s tax rules are connected in this UI prototype.</p><button id="switch-country" class="primary">Change country</button></div>`:screen==='result'?resultScreen():inputScreen();bind();state();}
function $$(s){return [...document.querySelectorAll(s)];}
function capture(){questions.forEach(q=>{const el=$('#'+q.key);if(el)data[q.key]=el.value.trim();});}
function validate(keys){for(const key of keys){let v=data[key];if(v==='')return [key,'Please '+(key==='registration'?'choose your registration status.':'enter '+questions.find(q=>q.key===key).label.toLowerCase()+'.')];if(key==='price'&&(!Number.isFinite(+v)||+v<=0||+v>1e12))return [key,'Enter a purchase price greater than zero and below one trillion.'];if(key==='share'&&(!Number.isFinite(+v)||+v<0||+v>100))return [key,'Business use must be between 0 and 100%.'];}return null;}
function bind(){ $('#purchase-form')?.addEventListener('submit',e=>{e.preventDefault();capture();const error=validate(view==='worksheet'?questions.map(q=>q.key):[questions[step].key]);if(error){$('#error').textContent=error[1];$('#'+error[0]).focus();state();return;}if(view==='worksheet'||step===3)screen='review';else step++;render();focusQuestion();});$$('[data-example]').forEach(b=>b.onclick=()=>{$('#item').value=b.dataset.example;$('#item').focus();});$$('[data-edit]').forEach(b=>b.onclick=()=>{capture();step=+b.dataset.edit;screen='input';render();focusQuestion();});$('#back')?.addEventListener('click',()=>{capture();if(screen==='review'){screen='input';step=3;}else step=Math.max(0,step-1);render();focusQuestion();});$('#check')?.addEventListener('click',()=>{screen='result';render();$('#workspace').scrollIntoView({behavior:'auto',block:'start'});const title=$('#workspace h2');title.tabIndex=-1;title.focus({preventScroll:true});});$('#edit-result')?.addEventListener('click',()=>{screen='review';render();});$('#new-result')?.addEventListener('click',reset);$('#sources')?.addEventListener('click',()=>panel('sources'));$('#switch-country')?.addEventListener('click',()=>$('#country').focus());$$('#purchase-form input,#purchase-form select').forEach(el=>el.addEventListener('input',()=>{capture();const summaryList=$('.summary dl');if(summaryList)summaryList.innerHTML=rows();state();}));}
function focusQuestion(){($('#'+questions[step].key)||$('#check'))?.focus({preventScroll:true});}
function state(){$('#state').textContent=JSON.stringify({prototype:true,view,screen,step:step+1,inputs:data,modelConnected:false,taxRulesConnected:false},null,2);}
function reset(){data={country:data.country,item:'',price:'',share:'',registration:''};step=0;screen='input';render();}
const contents={about:['About this prototype','<p>We’re exploring how Tikdam should feel before connecting a model or tax rules. Try all three interaction styles using the bottom bar.</p><p>All answers stay in memory and disappear when you reload. This page makes no API requests.</p><h3>What the result means</h3><p>The displayed business-use portion is simple purchase allocation. It is not an eligibility finding, deduction, or tax saving.</p>'],how:['A check in three parts','<ol><li>Tell Tikdam about the purchase and where you pay tax.</li><li>Answer the questions needed for the supported scenario.</li><li>Review the result, its assumptions, and evidence checklist.</li></ol><p>The finished app will use Muse Spark to gather information and explain results from verified rules and calculators.</p>'],coverage:['A deliberately small first version','<p>India and the United Kingdom are sample country selectors for this interaction study. Neither country has verified tax coverage in this prototype.</p><h3>Before a real launch</h3><p>We’ll define the exact taxpayer and purchase scenario, verify official sources, and publish coverage limits beside the country selector.</p>'],sources:['Sources & assumptions','<span class="status">Verification pending</span><h3>No legal sources connected yet</h3><p>The finished product must show official source links, relevant provisions, effective dates, and the rule version used for each assessment.</p><h3>This screen assumes</h3><ul><li>The price is the total amount entered by you.</li><li>The business-use percentage is your estimate.</li><li>Price × business-use share is allocation only.</li></ul><p>No tax treatment or savings have been assessed.</p>']};
function panel(key){lastFocus=document.activeElement;const [title,html]=contents[key];$('#drawer-content').innerHTML=`<h2 id="drawer-title">${title}</h2>${html}`;$('#shade').hidden=false;$('#drawer').hidden=false;document.body.style.overflow='hidden';$('#close').focus();}
function closePanel(){$('#drawer').hidden=true;$('#shade').hidden=true;document.body.style.overflow='';lastFocus?.focus();}
$('#close').onclick=closePanel;$('#shade').onclick=closePanel;
['about','how','coverage'].forEach(k=>$('#'+k).onclick=()=>panel(k));$('#restart').onclick=reset;
$('#country').onchange=e=>{capture();data.country=e.target.value;screen='input';step=0;render();};
$$('[data-view]').forEach(b=>b.onclick=()=>{capture();view=b.dataset.view;const u=new URL(location.href);u.searchParams.set('view',view);history.replaceState(null,'',u);render();});
$('#inspect').onclick=()=>{const open=$('#state').hidden;$('#state').hidden=!open;$('#inspect').setAttribute('aria-expanded',String(open));};
document.addEventListener('keydown',e=>{if(!$('#drawer').hidden){if(e.key==='Escape')closePanel();if(e.key==='Tab'){const focusables=$$('#drawer button,#drawer a');const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}return;}if(e.target.matches('input,select,textarea'))return;if(['1','2','3'].includes(e.key))$(`[data-view="${views[Number(e.key)-1]}"]`).click();});
render();
